mapper.select:
SELECT survey_id, title, description, start_date, end_date, status, reg_date, del_yn FROM TB_SURVEY WHERE del_yn = 'N'
AND title LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY survey_id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE TB_SURVEY
SET status = #{status}
WHERE survey_id = #{surveyId}
  AND del_yn = 'N'

UPDATE TB_SURVEY
SET del_yn = 'Y'
WHERE survey_id = #{surveyId}

